[standards/technology/nextjs/STD-TEC-NXT-001-coding.md#31-component-organization]

### 3.1 Component Organization

Organize components using a consistent structure:

```typescript
// 1. Imports
import { useState } from 'react';
import { Button } from '@/components/ui';
import styles from './ComponentName.module.css';

// 2. Types/Interfaces
interface ComponentProps {
    title: string;
    onAction: () => void;
}

// 3. Component Definition
export default function ComponentName({ title, onAction }: ComponentProps) {
    // 4. Hooks and State
    const [isOpen, setIsOpen] = useState(false);

    // 5. Derived State and Effects
    useEffect(() => {
        // Effect logic
    }, [dependencies]);

    // 6. Event Handlers
    const handleClick = () => {
        setIsOpen(!isOpen);
        onAction();
    };

    // 7. Render Methods/UI Components
    const renderHeader = () => <h2 className={styles.header}>{title}</h2>;

    // 8. Main Return
    return (
        <div className={styles.container}>
            {renderHeader()}
            <Button onClick={handleClick}>{isOpen ? 'Close' : 'Open'}</Button>
        </div>
    );
}
```

