[standards/technology/nextjs/STD-TEC-NXT-001-coding.md#52-context-api]

### 5.2 Context API

-   Create dedicated context providers for shared state
-   Split contexts by domain to prevent unnecessary re-renders
-   Provide proper typing for context values

```typescript
// auth-context.tsx
'use client';

import { createContext, useContext, useState } from 'react';

interface User {
    id: string;
    name: string;
}

interface AuthContextType {
    user: User | null;
    login: (credentials: { username: string; password: string }) => Promise<void>;
    logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
    const [user, setUser] = useState<User | null>(null);

    const login = async (credentials: { username: string; password: string }) => {
        // Login logic
        setUser({ id: '123', name: credentials.username });
    };

    const logout = () => {
        setUser(null);
    };

    return <AuthContext.Provider value={{ user, login, logout }}>{children}</AuthContext.Provider>;
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}
```
